def archive_directory(directory, dest_tar_path):
    if not isinstance(directory, str) or not isinstance(dest_tar_path, str):
        raise TypeError("directory and dest_tar_path must be strings")
    if directory.strip() == "" or dest_tar_path.strip() == "":
        raise ValueError("inputs must be non-empty")
    if not dest_tar_path.endswith(".tar"):
        raise ValueError("dest_tar_path must end with .tar")

    # Require real directories and normalize paths
    dir_abs = os.path.abspath(directory)
    dest_abs = os.path.abspath(dest_tar_path)

    if not os.path.isdir(dir_abs):
        raise FileNotFoundError("directory not found")

    # Basic hardening: disallow NUL and newlines in paths
    if any(ch in directory or ch in dest_tar_path for ch in ("\x00", "\n", "\r")):
        raise ValueError("invalid characters in path")

    # Ensure destination parent directory exists
    parent = os.path.dirname(dest_abs) or "."
    if not os.path.isdir(parent):
        raise FileNotFoundError("destination directory not found")

    try:
        # No shell; pass args as a list. Use -C to change directory safely.
        subprocess.check_output(["tar", "-cf", dest_abs, "-C", dir_abs, "."], text=True, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("tar failed") from e
    except FileNotFoundError as e:
        raise RuntimeError("tar not available") from e

    return f"Archived to {dest_abs}"

